                }
            }
        }
    }
    return count;
}

public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    if (start == null || end == null || paths == null) {
        return "cannot be travelled";
    }
    // Helper to convert coordinate array to a unique key
    java.util.function.Function<int[], String> coordToKey = (int[] coord) -> {
        if (coord == null || coord.length == 0) {
            return "";
        }
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < coord.length; i++) {
            if (i > 0) sb.append(',');
            sb.append(coord[i]);
        }
        return sb.toString();
    };
    String startKey = coordToKey.apply(start);
    String endKey = coordToKey.apply(end);
    if (startKey.equals(endKey)) {
        return "can be travelled";
    }
    java.util.Map<String, java.util.List<String>> graph = new java.util.HashMap<>();
    for (int[] path : paths) {
        if (path == null) continue;
        if (path.length == 4) {
            int[] c1 = new int[]{path[0], path[1]};
            int[] c2 = new int[]{path[2], path[3]};
            String k1 = coordToKey.apply(c1);
            String k2 = coordToKey.apply(c2);
            graph.computeIfAbsent(k1, k -> new java.util.ArrayList<>()).add(k2);
            graph.computeIfAbsent(k2, k -> new java.util.ArrayList<>()).add(k1);
        } else if (path.length == 2) {
            String k1 = String.valueOf(path[0]);
            String k2 = String.valueOf(path[1]);
            graph.computeIfAbsent(k1, k -> new java.util.ArrayList<>()).add(k2);
            graph.computeIfAbsent(k2, k -> new java.util.ArrayList<>()).add(k1);
        } else {
            // Unsupported path format; skip
            continue;
        }
    }
    // If start or end not in graph, cannot travel unless they are the same (handled above)
    if (!graph.containsKey(startKey) || !graph.containsKey(endKey)) {
        return "cannot be travelled";
    }
    java.util.Queue<String> queue = new java.util.ArrayDeque<>();
    java.util.Set<String> visited = new java.util.HashSet<>();
    queue.add(startKey);
    visited.add(startKey);
    while (!queue.isEmpty()) {
        String current = queue.poll();
        for (String neighbor : graph.getOrDefault(current, java.util.Collections.emptyList())) {
            if (neighbor.equals(endKey)) {
                return "can be travelled";
            }
            if (!visited.contains(neighbor)) {
                visited.add(neighbor);
                queue.add(neighbor);
            }
        }
    }
    return "cannot be travelled";
}

public static String convertDatesToWeekdays(String date) {
    try {
        String[] parts = date.trim().split("\\s+");
        if (parts.length != 3) {
            return "Invalid date format";
        }
        int month = Integer.parseInt(parts[0]);
        int day = Integer.parseInt(parts[1]);
        int year = Integer.parseInt(parts[2]);

        java.time.LocalDate localDate = java.time.LocalDate.of(year, month, day);
        java.util.Locale locale = java.util.Locale.ENGLISH;
        java.time.format.TextStyle full = java.time.format.TextStyle.FULL;

        String monthName = localDate.getMonth().getDisplayName(full, locale);
        String weekdayName = localDate.getDayOfWeek().getDisplayName(full, locale);

        return String.format("%s %d, %d is a %s", monthName, day, year, weekdayName);
    } catch (Exception e) {
        return "Invalid date format";
    }
}

public int[] twoSum(int[] nums, int target) {
    if (nums == null || nums.length < 2) {
        return new int[0];
    }
    java.util.Map<Integer, Integer> map = new java.util.HashMap<>();
    for (int i = 0; i < nums.length; i++) {
        int complement = target - nums[i];
        if (map.containsKey(complement)) {
            return new int[]{map.get(complement), i};
        }
