public int maxAbsoluteSum(int[] nums) {
    if (nums == null || nums.length == 0) {
        return 0;
    }
    int maxEnding = nums[0];
    int maxSoFar = nums[0];
    int minEnding = nums[0];
    int minSoFar = nums[0];
    for (int i = 1; i < nums.length; i++) {
        int val = nums[i];
        maxEnding = Math.max(val, maxEnding + val);
        maxSoFar = Math.max(maxSoFar, maxEnding);
        minEnding = Math.min(val, minEnding + val);
        minSoFar = Math.min(minSoFar, minEnding);
    }
    return Math.max(maxSoFar, -minSoFar);
}

public int findMinFibonacciNumbers(int k) {
    if (k <= 0) return 0;
    int[] fibs = new int[50];
    int size = 0;
    fibs[size++] = 1;
    fibs[size++] = 1;
    while (true) {
        long next = (long) fibs[size - 1] + fibs[size - 2];
        if (next > k) break;
        fibs[size++] = (int) next;
    }
    int count = 0;
    int remaining = k;
    for (int i = size - 1; i >= 0 && remaining > 0; i--) {
        int f = fibs[i];
        if (f <= remaining) {
            remaining -= f;
            count++;
        }
    }
    return count;
}

public int kthFactor(int n, int k) {
    if (k <= 0) return -1;
    java.util.ArrayList<Integer> small = new java.util.ArrayList<>();
    java.util.ArrayList<Integer> large = new java.util.ArrayList<>();
    for (int i = 1; i * i <= n; i++) {
        if (n % i == 0) {
            small.add(i);
            if (i != n / i) {
                large.add(n / i);
            }
        }
    }
    int total = small.size() + large.size();
    if (k > total) return -1;
    if (k <= small.size()) {
        return small.get(k - 1);
    } else {
        int idx = k - small.size();
        int largeIndex = large.size() - idx;
        return large.get(largeIndex);
    }
}

public String makeGood(String s) {
    if (s == null) {
        return null;
    }
    StringBuilder stack = new StringBuilder();
    for (int i = 0; i < s.length(); i++) {
        char c = s.charAt(i);
        int len = stack.length();
        if (len > 0) {
            char top = stack.charAt(len - 1);
            if (Character.toLowerCase(top) == Character.toLowerCase(c) && top != c) {
                stack.deleteCharAt(len - 1);
                continue;
            }
        }
        stack.append(c);
    }
    return stack.toString();
}

public int maxUniqueSplit(String s) {
    int[] max = new int[1];
    Set<String> used = new HashSet<>();
    dfs(0, used, max, s);
    return max[0];
}

private void dfs(int index, Set<String> used, int[] max, String s) {
    if (index == s.length()) {
        max[0] = Math.max(max[0], used.size());
        return;
    }
    for (int end = index + 1; end <= s.length(); end++) {
        String sub = s.substring(index, end);
        if (!used.contains(sub)) {
            used.add(sub);
            dfs(end, used, max, s);
            used.remove(sub);
        }
    }
}

public int minOperations(String[] logs) {
