        return 0;
    }
    for (String log : logs) {
        if (log == null || log.isEmpty()) {
            continue;
        }
        if ("../".equals(log)) {
            if (depth > 0) {
                depth--;
            }
        } else if ("./".equals(log)) {
            // stay in current folder
        } else if (log.endsWith("/")) {
            depth++;
        }
        // any other format is ignored
    }
    return depth;
}

public String getSmallestString(int n, int k) {
    // Validate input: the minimum possible sum is n (all 'a's), maximum is 26*n (all 'z's)
    if (n <= 0 || k < n || k > 26 * n) {
        return "";
    }
    // Start with all 'a's
    char[] result = new char[n];
    java.util.Arrays.fill(result, 'a');
    int remaining = k - n; // how much we need to add to reach the target sum
    // Increase characters from the end to keep the string lexicographically smallest
    for (int i = n - 1; i >= 0 && remaining > 0; i--) {
        int inc = Math.min(25, remaining); // maximum increment for a single character
        result[i] = (char) ('a' + inc);
        remaining -= inc;
    }
    return new String(result);
}

