public static java.util.List<Integer> findSteppingNumbers(int low, int high) {
    java.util.List<Integer> result = new java.util.ArrayList<>();
    if (high < low) {
        return result;
    }
    java.util.ArrayDeque<Long> queue = new java.util.ArrayDeque<>();
    // Include 0 if it falls within the range
    if (low == 0) {
        result.add(0);
    }
    // Initialize queue with single-digit numbers 1-9
    for (int d = 1; d <= 9; d++) {
        queue.add((long) d);
    }
    while (!queue.isEmpty()) {
        long num = queue.poll();
        if (num > high) {
            continue;
        }
        if (num >= low) {
            result.add((int) num);
        }
        int lastDigit = (int) (num % 10);
        if (lastDigit > 0) {
            long nextNum = num * 10 + (lastDigit - 1);
            if (nextNum <= high) {
                queue.add(nextNum);
            }
        }
        if (lastDigit < 9) {
            long nextNum = num * 10 + (lastDigit + 1);
            if (nextNum <= high) {
                queue.add(nextNum);
            }
        }
    }
    java.util.Collections.sort(result);
    return result;
}

public static int countDigitOne(int n) {
    if (n <= 0) {
        return 0;
    }
    long count = 0;
    long factor = 1;
    while (factor <= n) {
        long lower = n % factor;
        long cur = (n / factor) % 10;
        long higher = n / (factor * 10);
        count += higher * factor;
        if (cur == 1) {
            count += lower + 1;
        } else if (cur > 1) {
            count += factor;
        }
        factor *= 10;
    }
    return (int) count;
}

public static boolean isPowerOfTwo(int n) {
    if (n <= 0) {
        return false;
    }
    return (n & (n - 1)) == 0;
}

public static int addDigits(int num) {
    if (num < 0) {
        throw new IllegalArgumentException("num must be non-negative");
    }
    while (num >= 10) {
        int sum = 0;
        while (num > 0) {
            sum += num % 10;
            num /= 10;
        }
        num = sum;
    }
    return num;
}

public static int longestLine(int[][] mat) {
    if (mat == null || mat.length == 0 || mat[0].length == 0) {
        return 0;
    }
    int m = mat.length;
    int n = mat[0].length;
    int[][] dpH = new int[m][n];
    int[][] dpV = new int[m][n];
    int[][] dpD = new int[m][n];
    int[][] dpAD = new int[m][n];
    int maxLen = 0;
    for (int i = 0; i < m; i++) {
        for (int j = 0; j < n; j++) {
            if (mat[i][j] == 1) {
                dpH[i][j] = (j > 0 ? dpH[i][j - 1] : 0) + 1;
                dpV[i][j] = (i > 0 ? dpV[i - 1][j] : 0) + 1;
                dpD[i][j] = (i > 0 && j > 0 ? dpD[i - 1][j - 1] : 0) + 1;
                dpAD[i][j] = (i > 0 && j < n - 1 ? dpAD[i - 1][j + 1] : 0) + 1;
                int localMax = Math.max(Math.max(dpH[i][j], dpV[i][j]),
                                         Math.max(dpD[i][j], dpAD[i][j]));
                if (localMax > maxLen) {
                    maxLen = localMax;
                }
            } else {
                dpH[i][j] = dpV[i][j] = dpD[i][j] = dpAD[i][j] = 0;
            }
        }
    }
    return maxLen;
}

public static String addThousandSeparator(int n) {
    if (n == 0) {
        return "0";
    }
    boolean negative = n < 0;
    int absValue = Math.abs(n);
    String numStr = Integer.toString(absValue);
    StringBuilder sb = new StringBuilder();
    int count = 0;
    for (int i = numStr.length() - 1; i >= 0; i--) {
        sb.append(numStr.charAt(i));
        count++;
        if (count == 3 && i != 0) {
            sb.append('.');
            count = 0;
        }
    }
    sb.reverse();
    if (negative) {
        sb.insert(0, '-');
    }
    return sb.toString();
}

public static int squarePermutations(int[] A) {
    int n = A.length;
    if (n == 0) return 0;
    int maxVal = 0;
    for (int v : A) if (v > maxVal) maxVal = v;
    int maxSum = maxVal * 2;
    boolean[] isSquare = new boolean[maxSum + 1];
    for (int i = 0; i * i <= maxSum; i++) {
        isSquare[i * i] = true;
    }
    int fullMask = (1 << n) - 1;
    long[][] dp = new long[1 << n][n];
    for (int i = 0; i < n; i++) {
        dp[1 << i][i] = 1;
    }
    for (int mask = 1; mask <= fullMask; mask++) {
        for (int last = 0; last < n; last++) {
            long cur = dp[mask][last];
            if (cur == 0) continue;
            for (int next = 0; next < n; next++) {
                if ((mask & (1 << next)) != 0) continue;
                if (isSquare[A[last] + A[next]]) {
                    dp[mask | (1 << next)][next] += cur;
                }
            }
        }
    }
    long total = 0;
    for (int i = 0; i < n; i++) {
        total += dp[fullMask][i];
    }
    return (int) total;
}

public static int largestRectangleArea(int[] heights) {
    if (heights == null || heights.length == 0) {
        return 0;
    }
    int n = heights.length;
    int maxArea = 0;
    java.util.Deque<Integer> stack = new java.util.ArrayDeque<>();
    for (int i = 0; i <= n; i++) {
        int currentHeight = (i == n) ? 0 : heights[i];
        while (!stack.isEmpty() && currentHeight < heights[stack.peek()]) {
            int height = heights[stack.pop()];
            int width = stack.isEmpty() ? i : i - stack.peek() - 1;
            int area = height * width;
            if (area > maxArea) {
                maxArea = area;
            }
        }
        stack.push(i);
    }
    return maxArea;
}

public static int[] diagonalOrder(int[][] mat) {
    if (mat == null || mat.length == 0 || mat[0] == null || mat[0].length == 0) {
        return new int[0];
    }
    int m = mat.length;
    int n = mat[0].length;
    int[] result = new int[m * n];
    int i = 0, j = 0, d = 0; // d = 0 -> moving up, d = 1 -> moving down
    for (int k = 0; k < m * n; k++) {
        result[k] = mat[i][j];
        if (d == 0) { // moving up
            if (j == n - 1) {
                i++;
                d = 1;
            } else if (i == 0) {
                j++;
                d = 1;
            } else {
                i--;
                j++;
            }
        } else { // moving down
            if (i == m - 1) {
                j++;
                d = 0;
            } else if (j == 0) {
                i++;
                d = 0;
            } else {
                i++;
                j--;
            }
        }
    }
    return result;
}

